  1	import { test } from 'node:test';
  2	import assert from 'node:assert/strict';
  3	import {
  4	    extractHost,
  5	    injectCredentials,
  6	    injectCredentialToken,
  7	    resolveCredential,
  8	    hasEmbeddedCredentials,
  9	    stripEmbeddedCredentials,
 10	} from '../git/git-credentials.js';
 11	import type { GitCredentialEntry } from '../config/config.types.js';
 12	
 13	// ─── extractHost() ────────────────────────────────────────────────────────────
 14	
 15	test('extractHost() returns the hostname for a standard HTTPS URL', () => {
 16	    assert.strictEqual(extractHost('https://github.com/org/repo.git'), 'github.com');
 17	});
 18	
 19	test('extractHost() returns the hostname for an HTTPS URL with a port', () => {
 20	    assert.strictEqual(extractHost('https://gitlab.example.com:8443/org/repo.git'), 'gitlab.example.com');
 21	});
 22	
 23	test('extractHost() returns null for an SSH URL (git@ format)', () => {
 24	    assert.strictEqual(extractHost('git@github.com:org/repo.git'), null);
 25	});
 26	
 27	test('extractHost() returns null for an SSH URL (ssh:// scheme)', () => {
 28	    assert.strictEqual(extractHost('ssh://git@github.com/org/repo.git'), null);
 29	});
 30	
 31	test('extractHost() returns null for a git:// URL', () => {
 32	    assert.strictEqual(extractHost('git://github.com/org/repo.git'), null);
 33	});
 34	
 35	test('extractHost() returns null for an empty string', () => {
 36	    assert.strictEqual(extractHost(''), null);
 37	});
 38	
 39	test('extractHost() returns null for a malformed URL', () => {
 40	    assert.strictEqual(extractHost('not-a-url'), null);
 41	});
 42	
 43	test('extractHost() returns null for an http:// URL (non-HTTPS)', () => {
 44	    assert.strictEqual(extractHost('http://github.com/org/repo.git'), null);
 45	});
 46	
 47	// ─── injectCredentials() ──────────────────────────────────────────────────────
 48	
 49	test('injectCredentials() injects the token for a matching HTTPS host', () => {
 50	    const result = injectCredentials(
 51	        'https://github.com/org/repo.git',
